<script>
  import { $getRoot as getRoot, HISTORY_MERGE_TAG } from 'lexical';
  import { getContext, onMount, untrack } from 'svelte';
  import { on } from 'svelte/events';
  import { IMPORT_UPDATE_TAG } from './constants.js';
  import { handleEditorMouseDown, isStaticDecoratorContent } from './editing/caret.js';
  import { initEditor } from './core.js';
  import { mergeUnregisters } from './utils.js';

  /**
   * @import { ExportDetail } from './conversion/update.js';
   * @import { FormFieldStateProps, TextEditorStore, WidgetStateProps } from '../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {'ltr' | 'rtl' | 'auto'} [dir] Direction of the text. With `auto` or no value, each
   * paragraph takes the direction of its own text.
   */

  /**
   * @type {WidgetStateProps & FormFieldStateProps & Props & Record<string, any>}
   */
  let {
    /* eslint-disable prefer-const */
    dir = undefined,
    hidden = false,
    disabled = false,
    readonly = false,
    required = false,
    invalid = false,
    ...restProps
    /* eslint-enable prefer-const */
  } = $props();

  /** @type {TextEditorStore} */
  const editorStore = getContext('editorStore');

  /**
   * Reference to the Lexical editor root element.
   * @type {HTMLElement | undefined}
   */
  let lexicalRoot = $state();

  const editable = $derived(!(disabled || readonly));

  $effect(() => {
    editorStore.editor?.setEditable(editable);
  });

  $effect(() => {
    // Lexical owns the root element’s `dir` attribute, so set the direction on the root node, which
    // the paragraphs then follow. Without one, each paragraph gets `dir="auto"`
    const { editor } = editorStore;
    const direction = dir === 'ltr' || dir === 'rtl' ? dir : null;

    // Check first, as even an update that changes nothing makes the editor convert its content
    if (!editor || editor.getEditorState().read(() => getRoot().getDirection()) === direction) {
      return;
    }

    editor.update(
      () => {
        getRoot().setDirection(direction);
      },
      // Keep the change out of the undo history
      { tag: 'history-merge' },
    );
  });

  /**
   * Update the input value and the selection state whenever the editor exports its content.
   * @param {ExportDetail} detail Exported value and selection state.
   */
  const onExport = ({ value: exportedValue, selection }) => {
    const { hasConverterError, useRichText, inputValue } = editorStore;

    // The content has been converted, if it has changed at all
    editorStore.pending = false;

    // Ignore the content while a value is being imported, like the empty code block the editor
    // starts with: it would overwrite the value, which then replaces the content once imported
    if (hasConverterError || !useRichText || editorStore.importing) {
      return;
    }

    // Keep the value as given when the content is the one last imported, which the editor only
    // writes in its own Markdown style, e.g. `_text_` for `*text*`: that’s not a change, whether
    // the content is untouched or the user has undone their changes to it
    const newValue = editorStore.getImportedValue(exportedValue) ?? exportedValue;

    if (inputValue !== newValue) {
      editorStore.setExportedValue(newValue);
    }

    editorStore.selection = selection;
  };

  /**
   * Listen to `click` events on the editor. Ignore a click on a link, including one on the text
   * within it, which Lexical renders as a child element of the `<a>`.
   * @param {MouseEvent} event `click` event.
   */
  const onClick = (event) => {
    if (/** @type {HTMLElement} */ (event.target)?.closest('a')) {
      event.preventDefault();
    }
  };

  /**
   * Listen to `mousedown` events on the editor to place the caret where the user expects when the
   * pointer is not on any editable text, like on an editor component.
   * @param {MouseEvent} event `mousedown` event.
   */
  const onMouseDown = (event) => {
    if (editorStore.editor) {
      handleEditorMouseDown(editorStore.editor, event);
    }
  };

  // The state is updated within `untrack()` or a microtask below, because the browser fires these
  // events synchronously while it removes a focused element from the DOM, e.g. a nested editor in a
  // component being removed, in the middle of Svelte rendering, where a plain assignment would be
  // reported as an unsafe mutation. See also `<FloatingLinkEditor>`.

  /**
   * Check if the given element is a dialog other than the one the editor is in, if any, like a menu
   * opened from the toolbar of a nested editor, which is rendered outside the editor.
   * @param {Element | null} dialog Dialog element.
   * @returns {boolean} Result.
   */
  const isOtherDialog = (dialog) => !!dialog && !dialog.contains(lexicalRoot ?? null);

  /**
   * Interactive element in an editor component the pointer has just been pressed on, if any.
   * @type {Element | undefined}
   */
  let pressedComponentElement;

  /**
   * Track the pointer being pressed on an interactive element within an editor component. Safari
   * doesn’t focus a button on click, like one on the toolbar of a nested editor, and moves the
   * focus to the closest focusable ancestor, which is the root, or `<body>` instead. Neither is the
   * focus leaving the component. A press on its static content, like its label, does move the
   * focus to the root; see `handleEditorMouseDown()`.
   * @param {MouseEvent} event `mousedown` event.
   */
  const onComponentMouseDown = ({ target }) => {
    if (
      target instanceof Element &&
      target.closest('[data-lexical-decorator]') &&
      !isStaticDecoratorContent(target)
    ) {
      pressedComponentElement = target;
      window.setTimeout(() => {
        pressedComponentElement = undefined;
      });
    }
  };

  /**
   * Track the focus, to tell whether it’s in an editor component, like a nested editor or a field
   * of the component, rather than on the editor itself. The focus moving to another dialog doesn’t
   * change anything.
   * @param {FocusEvent} event `focusin` event.
   */
  const onFocusIn = ({ target }) => {
    const node = /** @type {Node} */ (target);

    if (lexicalRoot?.contains(node)) {
      // Safari moves the focus to the root when a button in a component is pressed; see above
      if (node === lexicalRoot && pressedComponentElement?.isConnected) {
        return;
      }

      untrack(() => {
        editorStore.componentHasFocus = node !== lexicalRoot;
      });
    } else if (!(node instanceof Element && isOtherDialog(node.closest('dialog')))) {
      untrack(() => {
        editorStore.componentHasFocus = false;
      });
    }
  };

  /**
   * Clear the state if the focus has left the editor component, landing on `<body>`, unless the
   * pointer has just been pressed within the component, or another modal dialog is open.
   */
  const checkComponentFocus = () => {
    // The update listener below may run within an effect, which mustn’t depend on the state
    untrack(() => {
      if (
        editorStore.componentHasFocus &&
        document.activeElement === document.body &&
        !pressedComponentElement?.isConnected &&
        ![...document.querySelectorAll(':modal')].some(isOtherDialog)
      ) {
        editorStore.componentHasFocus = false;
      }
    });
  };

  /**
   * Track the focus leaving a removed element, which doesn’t fire `focusin`. The event also comes
   * without a related target when a dialog opens, which only moves the focus into itself a moment
   * later, so the state is kept while another modal dialog is open. Firefox and Safari don’t fire
   * the event for a removed element at all; see the update listener below.
   * @param {FocusEvent} event `focusout` event.
   */
  const onFocusOut = ({ relatedTarget }) => {
    if (!relatedTarget) {
      queueMicrotask(checkComponentFocus);
    }
  };

  /**
   * Pass what was just typed on as soon as the focus leaves the editor, rather than after the
   * delay, so the value is up to date by the time the user acts on it, like with a button. That
   * includes a nested editor in a component, which passes the change on to this editor through the
   * component.
   * @param {FocusEvent} event `focusout` event.
   */
  const onRootFocusOut = ({ relatedTarget }) => {
    if (!lexicalRoot?.contains(/** @type {Node | null} */ (relatedTarget))) {
      // The root may be being removed; see above
      untrack(() => {
        editorStore.flushExport();
      });
    }
  };

  onMount(() => {
    const { editor, enabledTransformers, flush, dispose } = initEditor(editorStore.config, {
      onExport,
    });

    editorStore.editor = editor;
    editorStore.enabledTransformers = enabledTransformers;
    editorStore.flushExport = flush;

    // The root is bound before this runs
    const root = /** @type {HTMLElement} */ (lexicalRoot);

    const unregister = mergeUnregisters(
      on(root, 'focusout', onRootFocusOut),
      on(root, 'click', onClick),
      on(root, 'mousedown', onMouseDown),
      on(root, 'mousedown', onComponentMouseDown),
      on(document, 'focusin', onFocusIn),
      on(document, 'focusout', onFocusOut),
      // A change made by the user is converted to Markdown a moment later, so report it as pending
      // until then. An import, or an update that only changes how the content looks, e.g. the code
      // highlighting, isn’t a change
      editor.registerUpdateListener(({ dirtyElements, dirtyLeaves, tags }) => {
        if (
          (dirtyElements.size || dirtyLeaves.size) &&
          !tags.has(IMPORT_UPDATE_TAG) &&
          !tags.has(HISTORY_MERGE_TAG)
        ) {
          editorStore.pending = true;
        }

        // An editor component with the focus may have been removed, which doesn’t fire `focusout`
        // in Firefox and Safari
        checkComponentFocus();
      }),
    );

    return () => {
      // Pass on what was just typed, as Firefox and Safari don’t fire `focusout` when the focused
      // root is removed. This does nothing if the change has been passed on already
      flush();
      unregister();
      dispose();
      editor.setRootElement(null);
      editorStore.initialized = false;
      editorStore.editor = undefined;
    };
  });

  $effect(() => {
    // Both are in place by the time the effect first runs; see `onMount()` above
    /* v8 ignore else */
    if (editorStore.editor && lexicalRoot) {
      editorStore.editor.setRootElement(lexicalRoot);
      editorStore.initialized = true;
    }
  });
</script>

<div
  bind:this={lexicalRoot}
  {...restProps}
  role="textbox"
  aria-multiline={editorStore.config.multiline !== false}
  aria-hidden={hidden}
  aria-disabled={disabled}
  aria-readonly={readonly}
  aria-required={required}
  aria-invalid={invalid}
  class="lexical-root"
  class:code={editorStore.config.isCodeEditor}
  id={`${editorStore.editorId}-lexical-root`}
  contenteditable={editable}
  {hidden}
></div>

